"""Generate rv32_test.h from a project's own config.yaml.

rv32_test.h is the C header a test program #includes to end the test
the way the RISC-V HTIF convention does: a write to tohost. Generating
it keeps every consuming project from maintaining a copy that can drift
out of sync with its memory.tohost_addr.
"""

from pathlib import Path

#: Byte distance from tohost to fromhost: tohost is a 64-bit word.
FROMHOST_OFFSET = 8

_TEMPLATE = """\
/* Generated by riscv_tools.htif.generate_header from this project's
 * config.yaml (memory.tohost_addr); do not edit by hand, edit the
 * config and regenerate instead (`riscv-tools generate-header`).
 *
 * HTIF convention: tohost and fromhost are two 64-bit words, tohost at
 * RV32_TOHOST_ADDR and fromhost 8 bytes above it. A test ends by
 * writing tohost (low word, then the zero high word) and then calling
 * rv32_wait_restart() (implemented wherever this project's own boot
 * code lives, see the project's own paths.crt0/boot_rom in
 * config.yaml):
 *
 *   tohost low word = 1                    the test passed
 *   tohost low word = (code << 1) | 1      the test failed; code != 0
 *                                          names the failed check
 *
 * The host reads tohost over JTAG and restarts the core by writing a
 * nonzero value to fromhost (see riscv_tools.htif and
 * riscv_tools.orchestrator).
 *
 * The RVMODEL_* macros carry the names the riscv-arch-test (ACT4)
 * model uses, so an own test and an ACT4 test end the same way.
 */
#ifndef RV32_TEST_H
#define RV32_TEST_H

#define RV32_TOHOST_ADDR   ((volatile unsigned int *){tohost_hex})
#define RV32_FROMHOST_ADDR ((volatile unsigned int *){fromhost_hex})

extern void rv32_wait_restart(void) __attribute__((noreturn));

static inline void RV32_PASS(void) {{
    RV32_TOHOST_ADDR[0] = 1;
    RV32_TOHOST_ADDR[1] = 0;
    rv32_wait_restart();
}}

/* code 0 is not a valid failure code (tohost would read as the pass
 * encoding of 1), so it is reported as 1. */
static inline void RV32_FAIL_CODE(unsigned int code) {{
    if (code == 0)
        code = 1;
    RV32_TOHOST_ADDR[0] = (code << 1) | 1;
    RV32_TOHOST_ADDR[1] = 0;
    rv32_wait_restart();
}}

/* RV32_FAIL() reports code 1; RV32_FAIL(n) reports code n. */
#define RV32_FAIL(...) RV32_FAIL_CODE(1u * (__VA_ARGS__ +0))

#define RVMODEL_HALT_PASS RV32_PASS()
#define RVMODEL_HALT_FAIL(code) RV32_FAIL_CODE(code)

#endif /* RV32_TEST_H */
"""


def generate_header(tohost_addr: int) -> str:
    """Render rv32_test.h's content for a given tohost address.

    Parameters
    ----------
    tohost_addr : int
        Byte address of the 64-bit tohost word (memory.tohost_addr);
        fromhost sits 8 bytes above it.

    Returns
    -------
    str
        The full C header source.
    """
    return _TEMPLATE.format(
        tohost_hex=f"0x{tohost_addr:08X}",
        fromhost_hex=f"0x{tohost_addr + FROMHOST_OFFSET:08X}",
    )


def write_header(tohost_addr: int, out_path: Path) -> None:
    """Render and write rv32_test.h to out_path.

    Parameters
    ----------
    tohost_addr : int
        Byte address of tohost, passed to generate_header.
    out_path : Path
        Where to write the header (overwritten if it exists).
    """
    Path(out_path).write_text(generate_header(tohost_addr), encoding="utf-8")
